+    );
+    let end = render_screen(&pty.snapshot()).cursor;
+    pty.send(b"\x10");
+    wait_screen_row(&pty, "Commands", DEADLINE);
+    pty.send(b"\x1b");
+    dismissed(&pty, "Commands");
+    wait_cursor(&pty, end);
+    pty.send(b"\x1b[1;2D"); // select the chip
+    pty.send(b"\x10");
+    wait_screen_row(&pty, "Commands", DEADLINE);
+    pty.send(b"\x1b");
